select
question.*
from question question

    and question.id = #{id}
    and question.img = #{img}
    and question.title like concat('%',#{title},'%')
    and question.answer_a = #{answerA}
    and question.answer_b = #{answerB}
    and question.answer_c = #{answerC}
    and question.answer_d = #{answerD}
    and question.answer = #{answer}
    and question.status = #{status}
    and question.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from question question

    and question.id = #{id}
    and question.img = #{img}
    and question.title like concat('%',#{title},'%')
    and question.answer_a = #{answerA}
    and question.answer_b = #{answerB}
    and question.answer_c = #{answerC}
    and question.answer_d = #{answerD}
    and question.answer = #{answer}
    and question.status = #{status}
    and question.create_time = #{createTime}
